CREATE TABLE battery_asset (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL, battery_code VARCHAR(64) NOT NULL, serial_no VARCHAR(128) NOT NULL, model_code VARCHAR(64) NOT NULL, owner_org_id BIGINT NOT NULL, lifecycle_status VARCHAR(32) NOT NULL, health_status VARCHAR(32) NOT NULL DEFAULT 'NORMAL', current_location_type VARCHAR(32), current_location_id BIGINT, soc INT NOT NULL DEFAULT 0, soh DECIMAL(5,2) NOT NULL DEFAULT 100.00, version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE KEY uk_tenant_battery_code(tenant_id,battery_code), UNIQUE KEY uk_tenant_serial_no(tenant_id,serial_no), KEY idx_tenant_status(tenant_id,lifecycle_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE battery_status_history (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,battery_id BIGINT NOT NULL,from_status VARCHAR(32) NOT NULL,to_status VARCHAR(32) NOT NULL,reason VARCHAR(500) NOT NULL,operator_id BIGINT NOT NULL,occurred_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_battery_time(battery_id,occurred_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
